class Solution {
  public int minTime(int n, int[][] edges) {
    int[] head = new int[n], next = new int[edges.length];
    java.util.Arrays.fill(head, -1);
    for (int i = 0; i < edges.length; i++) {
      next[i] = head[edges[i][0]];
      head[edges[i][0]] = i;
    }
    long INF = Long.MAX_VALUE;
    long[] dist = new long[n];
    java.util.Arrays.fill(dist, INF);
    dist[0] = 0;
    java.util.PriorityQueue<long[]> pq =
        new java.util.PriorityQueue<>((a, b) -> Long.compare(a[0], b[0]));
    pq.add(new long[] {0, 0});
    while (!pq.isEmpty()) {
      long[] top = pq.poll();
      int u = (int) top[1];
      if (top[0] > dist[u]) continue;
      if (u == n - 1) return (int) top[0];
      for (int e = head[u]; e >= 0; e = next[e]) {
        if (top[0] > edges[e][3]) continue;
        long arrive = Math.max(top[0], edges[e][2]) + 1;
        int v = edges[e][1];
        if (arrive < dist[v]) {
          dist[v] = arrive;
          pq.add(new long[] {arrive, v});
        }
      }
    }
    return -1;
  }
}
